function capStars() { try { document.querySelectorAll(".stars").forEach((box: any) => { const cs = [...box.children] as any[]; cs.forEach(c => c.classList.remove("hid")); const tops: number[] = []; cs.forEach(c => { const t = c.offsetTop; if (!tops.includes(t)) tops.push(t); }); tops.sort((a, b) => a - b); const lim = tops[1] ?? tops[0]; let cut = false; cs.forEach(c => { if (cut || c.offsetTop > lim + 2) { cut = true; c.classList.add("hid"); } }); }); } catch (e) {} }
if (typeof window !== "undefined") window.addEventListener("resize", () => capStars());

