const rkey = (x: any) => x.k + "\u0001" + String(x.v).toLowerCase().replace(/\s+/g, " ").trim();
const stx = (x: any) => (x.s != null ? x.s : x.k === "search" && x.c > 1 ? x.c : 0);
function mergeRec(a: any[], b: any[]) { const m = new Map<string, any>(); [...(a || []), ...(b || [])].forEach((x: any) => { if (!x || !x.k) return; const k = rkey(x); const o = m.get(k); if (!o) { m.set(k, { ...x, s: stx(x) }); return; } m.set(k, { ...(x.t > o.t ? x : o), c: Math.max(o.c || 1, x.c || 1), s: Math.max(stx(o), stx(x)), t: Math.max(o.t || 0, x.t || 0) }); }); return [...m.values()].sort((x: any, y: any) => y.t - x.t).slice(0, 60); }
function idb(): Promise<any> { return new Promise((res, rej) => { try { const r = indexedDB.open("coinlookup", 1); r.onupgradeneeded = () => r.result.createObjectStore("kv"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); } catch (e) { rej(e); } }); }
function idbGet(k: string): Promise<any> { return idb().then((d: any) => new Promise((res) => { const q = d.transaction("kv").objectStore("kv").get(k); q.onsuccess = () => res(q.result); q.onerror = () => res(null); })); }
function idbSet(k: string, v: any): Promise<any> { return idb().then((d: any) => new Promise((res) => { const t = d.transaction("kv", "readwrite"); t.objectStore("kv").put(v, k); t.oncomplete = () => res(true); t.onerror = () => res(false); })); }
function Mi(props: { v: string }) { const [o, setO] = useState(false); useCloseAll(() => setO(false)); const n = Number(String(props.v).replace(/,/g, "")); const c = n >= 1e6 ? (n / 1e6).toFixed(n >= 1e7 ? 1 : 2).replace(/\.?0+$/, "") + "M" : n >= 1e4 ? Math.round(n / 1e3) + "K" : n >= 1e3 ? (n / 1e3).toFixed(1).replace(/\.0$/, "") + "K" : String(n); return <span class="nw" title={props.v} onClick={() => setO(!o)}>{o ? props.v : c}</span>; }
const mi = (v: any) => (typeof v === "string" && /^\d{1,3}(,\d{3})+$/.test(v.trim()) ? <Mi v={v.trim()} /> : v);
const clip = (v: any) => (typeof v === "string" && v.length > 52 ? v.slice(0, 50) + "…" : v);
const sv = (v: any): string | number | null => {
  if (v == null || v === "" || v === false) return null;
  if (typeof v === "object" && v.props && v.props.v != null) return Number(String(v.props.v).replace(/,/g, ""));
  if (typeof v === "object") { const c = v.props && v.props.children; return c == null ? null : String(c).toLowerCase(); }
  if (typeof v === "number") return v;
  const s = String(v).trim();
  if (!s || /^(unpriced|not sourced)/i.test(s)) return null;
  const m = s.match(/^[~$]?\s*([\d,]+(?:\.\d+)?)\s*(k|M)?/);
  if (m) { let n = Number(m[1].replace(/,/g, "")); if (m[2] === "k") n *= 1e3; if (m[2] === "M") n *= 1e6; return n; }
  return s.toLowerCase();
};
function CT(p0: { columns: string[]; rows: any[][]; ds?: number; sid?: string }) {
  const ord = p0.columns.map((c: string, i: number) => i).sort((a: number, b: number) => (/^(Issue|Type)$/.test(p0.columns[a]) ? 1 : 0) - (/^(Issue|Type)$/.test(p0.columns[b]) ? 1 : 0) || a - b);
  const mc = p0.columns.indexOf("Mintage");
  const props = { ds: p0.ds == null ? undefined : ord.indexOf(p0.ds), columns: ord.map((i: number) => p0.columns[i]), rows: p0.rows.map((r: any[]) => ord.map((i: number) => (i === mc ? mi(r[i]) : r[i]))) };
  const [sc, setSc] = useState(props.ds == null ? -1 : props.ds);
  const [dn, setDn] = useState(props.ds != null);
  const keep = props.columns.map((c: string, i: number) => i < 2 || props.rows.some((r: any[]) => r[i] !== "" && r[i] != null && r[i] !== false));
  let rows = props.rows;
  if (sc >= 0) rows = [...rows].sort((a: any[], b: any[]) => { const x = sv(a[sc]); const y = sv(b[sc]); if (x === null && y === null) return 0; if (x === null) return 1; if (y === null) return -1; const r = typeof x === "number" && typeof y === "number" ? x - y : typeof x === "number" ? -1 : typeof y === "number" ? 1 : String(x).localeCompare(String(y)); return dn ? -r : r; });
  const cols = props.columns.map((c: string, i: number) => ({ c, i })).filter((o: { c: string; i: number }) => keep[o.i]);
  const ic = props.columns.indexOf("Issue");
  const yc = ["Year", "Set"].map((n: string) => props.columns.indexOf(n)).find((i: number) => i >= 0) ?? -1;
  const cc = props.columns.indexOf("Coin") >= 0 ? props.columns.indexOf("Coin") : props.columns.indexOf("Round");
  const gcols = ["Worn", "AU", "MS62", "MS64", "Price", "Raw", "Price (worn)", "Top graded"].map((n: string) => ({ n, i: props.columns.indexOf(n) })).filter((x: { n: string; i: number }) => x.i >= 0);
  const [ix, setIx] = useState(false);
  const [ox, setOx] = useState<Record<number, 1>>({});
  useCloseAll(() => { setIx(false); setOx({}); });
  const isx = (r: any[]) => props.rows.indexOf(r);
  const money = (v: any) => { if (v == null || v === "" || v === "verify" || v === "unpriced" || v === "—" || v === "Not sourced" || v === "none") return null; if (typeof v === "number") return v > 0 ? v : null; const n = Number(String(v).replace(/[$,\s]/g, "")); return Number.isFinite(n) && n > 0 ? n : null; };
  const addBtn = (r: any[]) => {
    if (yc < 0 && cc < 0) return null;
    const lab = yc >= 0 ? String(r[yc] ?? "").replace(/\s*[↑↓].*$/, "").trim() : "generic";
    if (!lab) return null;
    const coin = cc >= 0 ? String(r[cc] ?? "") : "";
    const iss = ic >= 0 ? String(r[ic] ?? "") : "";
    const grades: Record<string, number | null> = {};
    gcols.forEach((g: { n: string; i: number }) => {
      const key = g.n === "Price" || g.n === "Raw" || g.n === "Price (worn)" ? "Raw" : g.n === "Top graded" ? "MS64" : g.n;
      const m = money(r[g.i]);
      if (grades[key] == null) grades[key] = m;
    });
    return <button type="button" class="addx" aria-label={"Add " + lab + " to collection"} onClick={(e: any) => { e.preventDefault(); e.stopPropagation(); dispatchEvent(new CustomEvent("cl-coll-add", { detail: { sid: p0.sid || "", lab, iss, coin, grades } })); }}>+</button>;
  };
  const cell = (r: any[], v: any, i: number) => {
    const core = (i !== ic || ix || v === "" || v == null ? v : ox[isx(r)] ? <span onClick={() => setOx((o) => { const n = { ...o }; delete n[isx(r)]; return n; })} style={{ cursor: "pointer" }}>{v} ◂</span> : <button aria-label="Show issue" onClick={() => setOx((o) => ({ ...o, [isx(r)]: 1 }))} style={{ border: 0, background: "none", padding: "4px 6px", font: "inherit", color: "inherit", minWidth: 28, minHeight: 28 }}>▸</button>);
    if (i === yc || (yc < 0 && i === cc)) return <span class="yradd"><span class="yrlab">{core}</span>{addBtn(r)}</span>;
    return core;
  };
  return (
    <div className={cols.map((o: { c: string; i: number }, k: number) => (/^(Price|×common|Mintage|Snag cap|Dealer|Premium|Prem\.|Bid cap|Melt now|AU|MS\d+|Worn|Top graded|MS64)/.test(o.c) ? "nc" + (k + 1) : "")).join(" ")} style={{ fontSize: 13, lineHeight: 1.25, maxWidth: "100%" }}>
      <Table onSort={(k: number) => { const oi = cols[k].i; if (oi === ic) { setIx(!ix); setOx({}); return; } if (oi === sc) setDn(!dn); else { setSc(oi); setDn(oi >= 3); } }} columns={cols.map((o: { c: string; i: number }) => (o.i === ic ? (ix ? "Issue ◂" : "▸") : (HD[o.c] || o.c) + (o.i === sc ? (dn ? " ↓" : " ↑") : "")))} rows={rows.map((r: any[]) => r.map((v: any, i: number) => [v, i] as [any, number]).filter((x: [any, number]) => keep[x[1]]).map((x: [any, number]) => cell(r, x[1] === ic ? x[0] : clip(x[0]), x[1])))} />
    </div>
  );
}

const NOTE: Record<string, [string, string]> = {
  search: ["Search tips", "Type a coin name (libertad, panda, morgan) to see every year. Add a year (1992 kook) to get that coin's card, or type just a year (1921) to see every coin dated that year. Mint marks work too (1916-D merc)."],
  recents: ["Recents", "Searches, families and bulk lots you use show up here. A star count appears only when you search, clear, then search the same thing again. Frequent lists items used 2+ times. Saved on this device when browser storage is available; otherwise they last for this visit only."],
  spot: ["Spot and melt", "Spot is the Kitco bid and refreshed daily by routine; the timestamp shows when. Melt = weight (g) × fineness ÷ 31.1035 × spot."],
  badges: ["Badges", "Key: hardest, most valuable dates (low mintage or heavy melting). Semi: scarcer than common, well below keys; often cheap worn, pricey in mint state. Better: a bit scarcer, modest premium. Var: die variety (overdate, doubled die, mint-mark style) worth more than the normal coin. '× common' = price vs. the series median. Sellers often call any old coin a key date; if it isn't marked Key or Semi here, pay common-date prices."],
  vals: ["Series values", "Mintages from USA Coin Book series tables. Values are PriceCharting sold-price guide columns (Ungraded as worn, AU, MS62, MS64) pulled Nov 2, 2026; blank means no PriceCharting entry for that date or variety. Empty columns are hidden."],
  bulk: ["Bulk units", "oz = avoirdupois (28.35 g), what kitchen/postal scales and sellers use. Troy oz (31.1 g) gives ~10% more coins. Subtract bags/rolls/tubes before converting. Steel 1943s (2.70 g) and Memorial cents mixed in skew counts and lower value; 1909-39 date lots sell ~3× higher."],
  wheat: ["Wheat prices", "Wheat sources (2026): eBay sold 1 lb unsearched 1909-58, $17.45 + $9.95 ship (Jan 17); eBay asks 1,000 wheats $89.95 (~9¢/coin + ship), 1 lb asks $13.62-$34.99; Maxsold ~5.5 lb mostly wheat + folder $235 (Feb 26, inflated). Other coin types: bulk premium not sourced; count and melt only."],
  ps: ["Proof set prices", "Proofsets.com dealer list prices (asks, not sold data), Nov 3, 2026; blank = not sourced. Melt uses the silver spot at top."],
  bullion: ["Bullion bid cap", "Melt is computed live from spot. Dealer price is SD Bullion's lowest tier on Nov 2, 2026. Never pay more than the dealer price shown, shipping included (melt plus the typical premium). On Whatnot, aim for melt plus about half that premium."],
  snag: ["Snag list and snag cap", "Snag list = the top 5 sold-price years per series, plus unpriced Key dates (e.g. 1995-W proof ASE, 1983-85 proof Pandas) as the real prizes. Snag cap is my rule of thumb, not a market figure: about 70% of typical sold price, but never below melt + 5%, and never above the sold price. Prices come from the sources already used for each series (PriceCharting for ASE; CoinGrader eBay sold for Panda, Kook, Maple, Britannia, Libertad, Philharmonic, Gold Eagle). Koala, Kangaroo, Elephant and Lunar were added from CoinGrader eBay sold data (Sep 2025–Jul 2026, years with 3+ sales). Lunar years mix Series I/II/III, and the 2023 Kangaroo price looks like an outlier, so check before trusting it. Krugerrand, Gold Buffalo and Queen's Beasts are still unpriced (CoinGrader's Krugerrand data mixes sizes and metals; Beasts has under 3 sales per year). Tell = mintage, badge, or note. Sold prices are from before the current spot, so melt can move the cap."],
  ase: ["Silver Eagle values", "Mintage: USA Coin Book. Values: PriceCharting sold guide, raw and top graded. Common-year raw ASEs sell for about $62–$103 vs. melt of one ounce. Blank cells mean PriceCharting has no data."],
  rounds: ["Rounds vs. coins", "Bid caps = spot + small premium, from live spot. Generic rounds (e.g. a CNT .9999 Buffalo round) have no year/denomination as legal tender and aren't U.S. coins, so they carry a lower premium but resell slightly weaker; dealers usually buy them back near spot. Vintage Engelhard, Johnson Matthey and Academy rounds are the exception: collectors pay extra."],
  fakes: ["Spotting fakes", "Silver and gold aren't magnetic, so try a magnet. Weigh on a 0.01 g scale, measure diameter and thickness with calipers, and use a ping-test app. A fake can pass one test but rarely passes all of them. Rounds: " + RFAKE],
};
