const medOf = (xs: number[]) => { const a = xs.filter((x: number) => x > 0).sort((x: number, y: number) => x - y); return a.length ? a[Math.floor(a.length / 2)] : 0; };
const CM: Record<string, number> = Object.fromEntries(SER.map((s: Ser) => [s.id, medOf(s.rows.map((r: R) => r.p || 0))]));
