const short = (n: string) => n.replace(/ \((silver|gold)[^)]*\)$/, (m: string, x: string) => " " + x).replace(/ 1 oz.*$/, "").replace(/^(American|Mexican|Chinese|Australian|Canadian|Austrian|British) /, "");
